<?php
declare(strict_types=1);require_once dirname(__DIR__).'/src/helpers.php';$user=require_login();if($user['role']!=='employee'){http_response_code(403);exit('Only MRs can add orders.');}$partyId=(int)($_GET['party_id']??$_POST['party_id']??0);$party=party_for_user($partyId,$user);if(!$party){http_response_code(404);exit('Party not found.');}$products=db()->query('SELECT id,name,rate,igst_rate FROM products WHERE active=1 ORDER BY name')->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$date=$_POST['order_date']??'';$items=$_POST['items']??[];$ids=array_map(fn($i)=>(int)($i['id']??0),is_array($items)?$items:[]);if(!$items||!DateTimeImmutable::createFromFormat('!Y-m-d',$date)){$error='Add at least one product and a valid date.';}else{$q=db()->prepare('SELECT * FROM products WHERE id IN ('.implode(',',array_fill(0,count($ids),'?')).')');$q->execute($ids);$map=[];foreach($q->fetchAll() as $p)$map[$p['id']]=$p;$lines=[];foreach($items as $i){$p=$map[(int)($i['id']??0)]??null;$qty=(int)($i['qty']??0);$free=max(0,(int)($i['free']??0));$mode=$i['mode']??'default';$custom=(float)($i['custom']??0);if(!$p||$qty<1||!in_array($mode,['default','inclusive','add'],true)){$error='Check all order lines.';break;}$rate=$mode==='default'?(float)$p['rate']:$custom;$gst=(float)$p['igst_rate'];if($mode==='inclusive'){$lineTotal=$rate*$qty;$tax=($rate-$rate/(1+$gst/100))*$qty;}else{$tax=$rate*$gst/100*$qty;$lineTotal=$rate*$qty+$tax;}$lines[]=[$p,$qty,$free,$rate,$gst,$tax,$lineTotal,$mode];}if(!$error){$pdo=db();$pdo->beginTransaction();try{$st=$pdo->prepare('INSERT INTO orders (party_id,mr_id,order_date,product,quantity,free_quantity,unit_rate,gst_rate,gst_amount,rate_mode,amount) VALUES (?,?,?,?,?,?,?,?,?,?,?)');foreach($lines as [$p,$qty,$free,$rate,$gst,$tax,$total,$mode])$st->execute([$partyId,$user['id'],$date,$p['name'],$qty,$free,$rate,$gst,$tax,$mode,$total]);$pdo->commit();redirect('party.php?id='.$partyId);}catch(Throwable $e){$pdo->rollBack();throw $e;}}}}
page_start('Add order: '.$party['name'],$user,'parties');?>
<form method="post" class="card" id="order-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="party_id" value="<?=$partyId?>"><input id="order-date" name="order_date" type="hidden" value="<?=e($_POST['order_date']??date('Y-m-d'))?>"><label>Order date (DD/MM/YYYY)<input id="order-date-display" inputmode="numeric" placeholder="DD/MM/YYYY" required></label><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><div id="lines"></div><button class="secondary" type="button" id="add">Add product</button><h2>Grand total: ₹<span id="total">0.00</span></h2><p class="muted">Default Rate is GST-exclusive. Free quantity has no value or GST.</p><button>Save order</button></form>
<script>const products=<?=json_encode($products,JSON_HEX_APOS|JSON_HEX_QUOT)?>,box=document.querySelector('#lines'),add=document.querySelector('#add'),grand=document.querySelector('#total');let n=0;function line(){let d=document.createElement('section');d.className='card';d.innerHTML=`<label>Product<select name="items[${n}][id]" class="p"><option value="">Choose product</option>${products.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><p class="info muted"></p><label>Rate type<select name="items[${n}][mode]" class="m"><option value="default">Default Rate + IGST</option><option value="inclusive">Custom rate (GST inclusive)</option><option value="add">Custom rate + add GST</option></select></label><label class="custom" hidden>Custom rate<input name="items[${n}][custom]" type="number" min="0" step="0.01"></label><div class="order-qty"><label>Quantity<input name="items[${n}][qty]" class="q" type="number" min="1" value="1"></label><label>Free quantity<input name="items[${n}][free]" type="number" min="0" value="0"></label></div><p>GST: ₹<span class="tax">0.00</span> · Total: ₹<strong class="sum">0.00</strong></p><button class="secondary remove" type="button">Remove</button>`;n++;d.oninput=d.onchange=()=>calc(d);d.querySelector('.remove').onclick=()=>{d.remove();all()};box.append(d);calc(d)}function calc(d){let p=products.find(x=>x.id==d.querySelector('.p').value),m=d.querySelector('.m').value,c=d.querySelector('.custom'),r=0,q=+d.querySelector('.q').value||0;if(!p)return;c.hidden=m==='default';r=m==='default'?+p.rate:+c.querySelector('input').value||0;let tax=m==='inclusive'?(r-r/(1+(+p.igst_rate)/100))*q:r*(+p.igst_rate)/100*q,total=m==='inclusive'?r*q:r*q+tax;d.querySelector('.info').textContent=`Rate ₹${(+p.rate).toFixed(2)} + IGST ${p.igst_rate}%`;d.querySelector('.tax').textContent=tax.toFixed(2);d.querySelector('.sum').textContent=total.toFixed(2);all()}function all(){grand.textContent=[...document.querySelectorAll('.sum')].reduce((a,x)=>a+(+x.textContent||0),0).toFixed(2)}add.onclick=line;line();</script><?php page_end($user,'parties');?>
